//! Resharing as the client drives it. A "quote" is the binding itself.

use super::reshare::*;
use super::*;

const OLD: &str = "users/sub/k";
const NEW: &str = "users/sub/k/v2";
const NOW: u64 = 1_800_000_000;
const CTX: [u8; 32] = [5u8; 32];

fn fake_verify(quote: &[u8], binding: &[u8; 32]) -> Result<(), String> {
    if quote == binding {
        Ok(())
    } else {
        Err("quote does not bind this message".into())
    }
}

/// A key generated by DKG among `n` vaults, threshold `t`: the shares.
fn keygen(t: u16, n: u16) -> Vec<StoredShare> {
    let sid = new_session_id();
    let ctx = [1u8; 32];
    let mut stores: Vec<DkgStore> = (0..n).map(|_| DkgStore::new()).collect();
    let mut r1 = BTreeMap::new();
    for i in 1..=n {
        let o = stores[usize::from(i) - 1].round1(&sid, OLD, &ctx, i, t, n, NOW).unwrap();
        r1.insert(i, Round1Msg { package: o.package, dh_public: o.dh_public, quote: o.binding.to_vec() });
    }
    let mut sealed = BTreeMap::new();
    for i in 1..=n {
        sealed.insert(i, stores[usize::from(i) - 1].round2(&sid, OLD, &r1, &fake_verify, NOW).unwrap());
    }
    let route = |m: &BTreeMap<u16, BTreeMap<u16, Vec<u8>>>, to: u16| -> BTreeMap<u16, Vec<u8>> {
        m.iter().filter(|(f, _)| **f != to).map(|(f, x)| (*f, x[&to].clone())).collect()
    };
    let mut conf = BTreeMap::new();
    for i in 1..=n {
        conf.insert(i, stores[usize::from(i) - 1].round3(&sid, OLD, &route(&sealed, i), NOW).unwrap().confirmations);
    }
    (1..=n)
        .map(|i| stores[usize::from(i) - 1].commit(&sid, OLD, &route(&conf, i), NOW).unwrap())
        .collect()
}

struct Run {
    sid: String,
    targets: BTreeMap<u16, TargetMsg>,
    stores: Vec<ReshareStore>,
    deals: BTreeMap<u16, Deal>,
}

fn start(old: &[StoredShare], helpers: &[u16], t2: u16, n2: u16) -> Run {
    let sid = new_session_id();
    let pkp = old[0].public_key_package.clone();
    let mut stores: Vec<ReshareStore> = (0..n2).map(|_| ReshareStore::new()).collect();
    let mut targets = BTreeMap::new();
    for j in 1..=n2 {
        let o = stores[usize::from(j) - 1].round1(&sid, NEW, &CTX, j, t2, n2, &pkp, helpers, NOW).unwrap();
        targets.insert(j, TargetMsg { dh_public: o.dh_public, quote: o.binding.to_vec() });
    }
    Run { sid, targets, stores, deals: BTreeMap::new() }
}

fn deal_all(old: &[StoredShare], r: &mut Run, helpers: &[u16], t2: u16, n2: u16) {
    for h in helpers {
        let d = deal(&old[usize::from(*h) - 1], &r.sid, NEW, &CTX, helpers, t2, n2, &r.targets, &fake_verify).unwrap();
        r.deals.insert(*h, d);
    }
}

fn for_target(r: &Run, j: u16) -> BTreeMap<u16, (Vec<Vec<u8>>, Vec<u8>)> {
    r.deals.iter().map(|(h, d)| (*h, (d.commitment.clone(), d.sealed[&j].clone()))).collect()
}

fn finish(r: &mut Run, n2: u16) -> Result<Vec<StoredShare>, String> {
    let mut conf = BTreeMap::new();
    for j in 1..=n2 {
        let deals = for_target(r, j);
        let out = r.stores[usize::from(j) - 1].round2(&r.sid, NEW, &r.targets, &deals, &fake_verify, NOW)?;
        conf.insert(j, out.confirmations);
    }
    let mut shares = Vec::new();
    for j in 1..=n2 {
        let mine: BTreeMap<u16, Vec<u8>> =
            conf.iter().filter(|(f, _)| **f != j).map(|(f, c)| (*f, c[&j].clone())).collect();
        shares.push(r.stores[usize::from(j) - 1].commit(&r.sid, NEW, &mine, NOW)?);
    }
    Ok(shares)
}

fn reshare(old: &[StoredShare], helpers: &[u16], t2: u16, n2: u16) -> Result<Vec<StoredShare>, String> {
    let mut r = start(old, helpers, t2, n2);
    deal_all(old, &mut r, helpers, t2, n2);
    finish(&mut r, n2)
}

fn sign(shares: &[StoredShare], signers: &[u16], msg: &[u8]) -> Result<Vec<u8>, String> {
    let sid = new_session_id();
    let mut stores: BTreeMap<u16, SignStore> = signers.iter().map(|i| (*i, SignStore::new())).collect();
    let mut c = BTreeMap::new();
    for i in signers {
        c.insert(*i, stores.get_mut(i).unwrap().commit(&sid, NEW, &shares[usize::from(*i) - 1], msg, NOW)?);
    }
    let mut sh = BTreeMap::new();
    for i in signers {
        sh.insert(*i, stores.get_mut(i).unwrap().sign(&sid, NEW, &shares[usize::from(*i) - 1], &c, NOW)?);
    }
    aggregate(msg, &c, &sh, &shares[usize::from(signers[0]) - 1])
}

#[test]
fn lagrange_weights_add_up() {
    // Σ λ_i over any set is 1 (it interpolates the constant polynomial 1).
    use curve25519_dalek::scalar::Scalar;
    let set = [1u16, 3, 4];
    let sum = set.iter().fold(Scalar::ZERO, |a, i| a + super::reshare::lagrange(*i, &set));
    assert_eq!(sum, Scalar::ONE);
}

#[test]
fn moves_a_key_to_a_new_set_with_the_same_public_key() {
    let old = keygen(2, 3);
    let pk = old[0].group_public_key().unwrap();
    // To 4 new vaults, threshold 3, dealt by old vaults 1 and 3.
    let new = reshare(&old, &[1, 3], 3, 4).unwrap();
    for s in &new {
        assert_eq!(s.group_public_key().unwrap(), pk, "the group key never changes");
        assert_eq!((s.min_signers, s.max_signers), (3, 4));
    }
    let sig = sign(&new, &[1, 2, 4], b"after the move").unwrap();
    verify(&pk, b"after the move", &sig).unwrap();
    assert!(sign(&new, &[1, 2], b"x").is_err(), "the new threshold applies");
}

#[test]
fn renews_in_place_and_old_shares_no_longer_combine() {
    let old = keygen(2, 2);
    let pk = old[0].group_public_key().unwrap();
    let new = reshare(&old, &[1, 2], 2, 2).unwrap();
    assert_eq!(new[0].group_public_key().unwrap(), pk);
    assert_ne!(new[0].key_package, old[0].key_package, "every share changes");
    verify(&pk, b"renewed", &sign(&new, &[1, 2], b"renewed").unwrap()).unwrap();
    // An old share with a new one belongs to two different polynomials.
    let mixed = vec![old[0].clone(), new[1].clone()];
    assert!(sign(&mixed, &[1, 2], b"mixed").is_err());
}

#[test]
fn shrinks_to_a_subset() {
    let old = keygen(2, 3);
    let pk = old[0].group_public_key().unwrap();
    let new = reshare(&old, &[2, 3], 2, 2).unwrap();
    verify(&pk, b"m", &sign(&new, &[1, 2], b"m").unwrap()).unwrap();
}

#[test]
fn too_few_helpers_cannot_reshare() {
    let old = keygen(3, 4);
    let r = start(&old, &[1, 2, 3], 2, 2);
    let e = deal(&old[0], &r.sid, NEW, &CTX, &[1, 2], 2, 2, &r.targets, &fake_verify).unwrap_err();
    assert!(e.contains("at least 3"), "{e}");
    let e = ReshareStore::new()
        .round1(&new_session_id(), NEW, &CTX, 1, 2, 2, &old[0].public_key_package, &[1, 2], NOW)
        .err()
        .unwrap();
    assert!(e.contains("at least 3"), "{e}");
}

#[test]
fn a_helper_deals_only_to_attested_vaults() {
    let old = keygen(2, 2);
    let mut r = start(&old, &[1, 2], 2, 2);
    // The client swaps in its own X25519 key for new vault 2.
    r.targets.get_mut(&2).unwrap().dh_public = vec![9u8; 32];
    let e = deal(&old[0], &r.sid, NEW, &CTX, &[1, 2], 2, 2, &r.targets, &fake_verify).unwrap_err();
    assert!(e.contains("new vault 2"), "{e}");
}

#[test]
fn a_client_polynomial_is_refused() {
    // A deal of another key's share: its constant term is not λ_i · Y_i.
    let old = keygen(2, 2);
    let other = keygen(2, 2);
    let mut r = start(&old, &[1, 2], 2, 2);
    deal_all(&old, &mut r, &[1, 2], 2, 2);
    let forged = deal(&other[0], &r.sid, NEW, &CTX, &[1, 2], 2, 2, &r.targets, &fake_verify).unwrap();
    r.deals.insert(1, forged);
    let e = finish(&mut r, 2).err().unwrap();
    assert!(e.contains("helper 1") && e.contains("not of its share"), "{e}");
}

#[test]
fn a_forged_commitment_on_a_real_constant_is_refused() {
    // The right C_0, another C_1: the pieces no longer match.
    let old = keygen(2, 2);
    let mut r = start(&old, &[1, 2], 2, 2);
    deal_all(&old, &mut r, &[1, 2], 2, 2);
    let c1 = r.deals[&2].commitment[1].clone();
    r.deals.get_mut(&1).unwrap().commitment[1] = c1;
    let e = finish(&mut r, 2).err().unwrap();
    assert!(e.contains("helper 1"), "{e}");
}

#[test]
fn a_piece_opens_only_for_its_vault() {
    let old = keygen(2, 2);
    let mut r = start(&old, &[1, 2], 2, 3);
    deal_all(&old, &mut r, &[1, 2], 2, 3);
    let to_2 = r.deals[&1].sealed[&2].clone();
    r.deals.get_mut(&1).unwrap().sealed.insert(3, to_2);
    let deals = for_target(&r, 3);
    let e = r.stores[2].round2(&r.sid, NEW, &r.targets, &deals, &fake_verify, NOW).err().unwrap();
    assert!(e.contains("helper 1") && e.contains("does not open"), "{e}");
}

#[test]
fn every_helper_must_deal() {
    let old = keygen(2, 3);
    let mut r = start(&old, &[1, 2], 2, 2);
    deal_all(&old, &mut r, &[1, 2], 2, 2);
    r.deals.remove(&2);
    let e = finish(&mut r, 2).err().unwrap();
    assert!(e.contains("each helper"), "{e}");
}

#[test]
fn new_vaults_must_confirm_the_same_transcript() {
    let old = keygen(2, 2);
    let mut r = start(&old, &[1, 2], 2, 2);
    deal_all(&old, &mut r, &[1, 2], 2, 2);
    let d1 = for_target(&r, 1);
    let d2 = for_target(&r, 2);
    let c1 = r.stores[0].round2(&r.sid, NEW, &r.targets, &d1, &fake_verify, NOW).unwrap().confirmations;
    let _ = r.stores[1].round2(&r.sid, NEW, &r.targets, &d2, &fake_verify, NOW).unwrap();
    let mut forged = BTreeMap::new();
    forged.insert(2u16, vec![0u8; 32]);
    let e = r.stores[0].commit(&r.sid, NEW, &forged, NOW).err().unwrap();
    assert!(e.contains("did not confirm"), "{e}");
    let mut mine = BTreeMap::new();
    mine.insert(1u16, c1[&2].clone());
    assert!(r.stores[1].commit(&r.sid, NEW, &mine, NOW).is_ok());
}
